const PLATFORM_ICONS = {
  windows: <WindowsIcon />,
  mac: <MacIcon />,
  linux: <LinuxIcon size={24} />,
};

/** Centred against the image panel band (150..720) as in Figma. */
const LEFT_TOP = 262;

/**
 * Figma: 1440×720, background #000000
 */
export default function Mt5HeroSection() {
  return (
    <section
      className="mt5-hero"
      style={{
        position: "relative",
        background: "#000000",
        width: "100%",
        maxWidth: 1440,
        margin: "0 auto",
        minHeight: "clamp(480px, 50vw, 720px)",
        height: 720,
        overflow: "hidden",
        boxSizing: "border-box",
      }}
    >
      <div
        className="mt5-hero-image-wrap"
        style={{
          position: "absolute",
          top: 150,
          left: 680,
          width: 760,
          height: 570,
          overflow: "hidden",
          zIndex: 1,
        }}
      >
        <Image
          src="/mt5-assets/hero.jpeg"
          alt="MetaTrader 5 multi-asset trading visualization"
          fill
          sizes="(max-width: 900px) 100vw, 760px"
          className="mt5-hero-image"
          priority
          style={{ objectFit: "cover", objectPosition: "center" }}
        />
      </div>

      {/* Entire left column (title + desc + CTAs) — one offset control */}
      <div
        className="mt5-hero-left"
        style={{
          position: "absolute",
          top: LEFT_TOP,
          left: 64,
          width: 600,
          display: "flex",
          flexDirection: "column",
          gap: 24,
          zIndex: 2,
        }}
      >
        <h1
          className="mt5-hero-title"
          style={{
            margin: 0,
            /* Figma dev spec: Sora / 600 SemiBold / 56px / 110% / -1% */
            maxWidth: 600,
            fontFamily: "var(--font-sora, Sora)",
            fontWeight: 600,
            fontSize: "clamp(34px, 3.9vw, 56px)",
            lineHeight: "110%",
            letterSpacing: "-0.01em",
            color: "#E2E2E3",
          }}
        >
          Trade Global Markets with MetaTrader 5 (MT5)
        </h1>

        <p
          className="mt5-hero-desc"
          style={{
            margin: 0,
            maxWidth: 500,
            fontFamily: "var(--font-inter, Inter)",
            fontWeight: 400,
            fontSize: 16,
            lineHeight: "26px",
            letterSpacing: "0%",
            color: "#7D7F84",
          }}
        >
          Trade Forex, Stocks, Indices, Commodities, and Metals on the powerful
          MetaTrader 5 (MT5) trading platform.
        </p>

        <div
          className="mt5-hero-ctas"
          style={{
            display: "flex",
            flexWrap: "wrap",
            gap: 12,
          }}
        >
          {MT5_DOWNLOADS.map((item) => (
            <a
              key={item.platform}
              href={item.href}
              target="_blank"
              rel="noopener noreferrer"
              style={{
                boxSizing: "border-box",
                display: "inline-flex",
                alignItems: "center",
                justifyContent: "flex-start",
                gap: 10,
                width: 158,
                height: 48,
                paddingLeft: 12,
                paddingRight: 10,
                borderRadius: 4.87,
                border: "0.81px solid #0164BC",
                background: "#000000",
                color: "#FFFFFF",
                textDecoration: "none",
              }}
            >
              <span
                style={{
                  display: "inline-flex",
                  alignItems: "center",
                  justifyContent: "center",
                  flexShrink: 0,
                  width: 26,
                  height: 26,
                }}
              >
                {PLATFORM_ICONS[item.platform]}
              </span>
              <span
                style={{
                  display: "flex",
                  flexDirection: "column",
                  justifyContent: "center",
                  gap: 2,
                  minWidth: 0,
                }}
              >
                <span
                  style={{
                    fontFamily: "var(--font-inter, Inter)",
                    fontWeight: 300,
                    fontSize: 12.2,
                    lineHeight: "100%",
                    color: "#FFFFFF",
                  }}
                >
                  Download for
                </span>
                <span
                  style={{
                    fontFamily: "var(--font-inter, Inter)",
                    fontWeight: 500,
                    fontSize: 13.2,
                    lineHeight: "100%",
                    color: "#FFFFFF",
                  }}
                >
                  {PLATFORM_LABELS[item.platform]}
                </span>
              </span>
            </a>
          ))}
        </div>
      </div>
    </section>
  );
}
